var maximumSaleItems = function (items, budget) {
    const n = items.length;
    const pq = new MinPriorityQueue(el => el[0]);

    for (let i = 0; i < n; i++) {
        let units = 1;

        for (let j = 0; j < n; j++) {
            if (i !== j && items[j][0] % items[i][0] === 0) {
                units++;
            }
        }

        pq.enqueue([items[i][1] / units, units]);
        pq.enqueue([items[i][1], Infinity]);
    }

    let count = 0;

    while (!pq.isEmpty() && budget > 0) {
        const [price, quantity] = pq.dequeue();
        let buy = 0;

        if (quantity === Infinity) {
            buy = Math.floor(budget / price);
        } else if (budget >= quantity * price) {
            buy = quantity;
        }

        count += buy;
        budget -= buy * price;
    }

    return count;
};

